// Title: C# – Deserialize cell JSON and restore rich‑text formatting with Aspose.Cells for .NET
// Description: Demonstrates how to read a cell's JSON (including the Characters array) generated by Aspose.Cells, rebuild FontSetting objects, apply them with SetCharacters, and save the workbook with the original rich‑text styling intact.
// Keywords: Aspose.Cells deserialize JSON | C# rich text cell | cell.ToJson example | SetCharacters from JSON | FontSetting reconstruction | Aspose.Cells .NET tutorial | restore cell formatting | JSON rich‑text serialization
// Common Searches: Aspose.Cells C# deserialize cell JSON | restore rich text from JSON Aspose.Cells | cell.ToJson and SetCharacters example | how to reapply font settings from JSON Aspose | Aspose.Cells rich‑text serialization tutorial
// Developer Intent: Read a previously saved JSON representation of a worksheet cell and reapply its rich‑text formatting to the same cell using Aspose.Cells for .NET.
// Use Cases: Persist cell rich‑text styles as JSON for reuse across multiple workbooks. | Transfer formatted cell content between applications by serializing to JSON and deserializing with Aspose.Cells. | Implement an undo/redo feature that stores cell formatting as JSON and restores it on demand.
// AI Prompts: Write C# code that parses a cell JSON produced by Aspose.Cells and restores its rich‑text formatting using FontSetting and SetCharacters. | Create a reusable method that accepts a JSON string containing a Characters array and applies the corresponding FontSettings to an Aspose.Cells cell. | Explain how to convert hex color strings from Aspose.Cells JSON into System.Drawing.Color objects when rebuilding font styles.

using System;
using System.Drawing;
using System.IO;
using System.Text.Json;
using Aspose.Cells;
using Aspose.Cells.Drawing.Texts;

namespace AsposeCellsRichTextJsonDemo
{
    // Demonstrates how to read a cell's JSON (including the Characters array) generated by Aspose.Cells, rebuild FontSetting objects, apply them with SetCharacters, and save the workbook with the original rich‑text styling intact.
    class Program
    {
        static void Main()
        {
            // ------------------------------------------------------------
            // 1. Create a workbook and apply rich‑text formatting to A1
            // ------------------------------------------------------------
            Workbook wb = new Workbook();
            Worksheet ws = wb.Worksheets[0];
            Cell cell = ws.Cells["A1"];
            cell.PutValue("Hello World!");

            // Apply bold to "Hello"
            FontSetting part1 = cell.Characters(0, 5);
            part1.Font.IsBold = true;
            part1.Font.Color = Color.Red;

            // Apply italic to "World"
            FontSetting part2 = cell.Characters(6, 5);
            part2.Font.IsItalic = true;
            part2.Font.Color = Color.Blue;

            // Commit the formatting
            cell.SetCharacters(new FontSetting[] { part1, part2 });

            // ------------------------------------------------------------
            // 2. Serialize the cell (including rich‑text info) to JSON
            // ------------------------------------------------------------
            string cellJson = cell.ToJson();
            const string jsonPath = "cell.json";
            File.WriteAllText(jsonPath, cellJson);
            Console.WriteLine("Cell serialized to JSON:");
            Console.WriteLine(cellJson);
            Console.WriteLine();

            // ------------------------------------------------------------
            // 3. Clear the cell content to simulate a fresh load
            // ------------------------------------------------------------
            cell.PutValue(string.Empty);
            // Ensure no formatting remains
            cell.SetCharacters(Array.Empty<FontSetting>());

            // ------------------------------------------------------------
            // 4. Deserialize the JSON and reapply the rich‑text formatting
            // ------------------------------------------------------------
            string loadedJson = File.ReadAllText(jsonPath);
            using JsonDocument doc = JsonDocument.Parse(loadedJson);
            JsonElement root = doc.RootElement;

            // The JSON produced by Aspose.Cells contains a "Characters" array
            // with each element having "StartIndex", "Length" and a nested "Font" object.
            if (root.TryGetProperty("Characters", out JsonElement charactersElem) && charactersElem.ValueKind == JsonValueKind.Array)
            {
                var fontSettings = new FontSetting[charactersElem.GetArrayLength()];
                int idx = 0;

                foreach (JsonElement charElem in charactersElem.EnumerateArray())
                {
                    int start = charElem.GetProperty("StartIndex").GetInt32();
                    int length = charElem.GetProperty("Length").GetInt32();

                    // Create a FontSetting for the specified range
                    FontSetting fs = cell.Characters(start, length);

                    // Font properties may include IsBold, IsItalic, Color, etc.
                    if (charElem.TryGetProperty("Font", out JsonElement fontElem))
                    {
                        if (fontElem.TryGetProperty("IsBold", out JsonElement boldElem))
                            fs.Font.IsBold = boldElem.GetBoolean();

                        if (fontElem.TryGetProperty("IsItalic", out JsonElement italicElem))
                            fs.Font.IsItalic = italicElem.GetBoolean();

                        if (fontElem.TryGetProperty("Color", out JsonElement colorElem) && colorElem.ValueKind == JsonValueKind.String)
                        {
                            // Color is stored as a string like "#FF0000"
                            try
                            {
                                fs.Font.Color = ColorTranslator.FromHtml(colorElem.GetString());
                            }
                            catch
                            {
                                // Fallback: ignore invalid color strings
                            }
                        }

                        // Additional font attributes can be handled similarly (Size, Name, etc.)
                    }

                    fontSettings[idx++] = fs;
                }

                // Apply all collected FontSetting objects back to the cell
                cell.SetCharacters(fontSettings);
            }

            // ------------------------------------------------------------
            // 5. Save the workbook to verify the rich‑text is restored
            // ------------------------------------------------------------
            wb.Save("RichTextRestored.xlsx");
            Console.WriteLine("Workbook saved as RichTextRestored.xlsx with rich‑text reapplied.");
        }
    }
}
